type SQLRegistry struct{ DB *sql.DB }

func (r SQLRegistry) Sync(ctx context.Context, accountID string, items []Resource) error {
	tx,err:=r.DB.BeginTx(ctx,nil); if err!=nil{return err}; defer tx.Rollback()
	for _,item:=range items {
		if item.AccountID!=accountID{return ErrTenantMismatch}
		metadata,_:=json.Marshal(item.Metadata)
		_,err=tx.ExecContext(ctx,`INSERT INTO resources(id,account_id,provider,provider_resource_id,type,state,managed,metadata,created_at,updated_at) VALUES(gen_random_uuid(),$1,$2,$3,$4,$5,$6,$7,now(),now()) ON CONFLICT(account_id,provider,type,provider_resource_id) DO UPDATE SET state=EXCLUDED.state,metadata=EXCLUDED.metadata,updated_at=now()`,item.AccountID,item.Provider,item.ProviderResourceID,item.Type,item.State,item.Managed,metadata)

		if err!=nil{return err}
	}
	return tx.Commit()
}

func (r SQLRegistry) Find(ctx context.Context, accountID string)([]Resource,error){
	rows,err:=r.DB.QueryContext(ctx,`SELECT id::text,account_id::text,provider,provider_resource_id,type,state,managed,metadata,created_at,updated_at FROM resources WHERE account_id=$1`,accountID); if err!=nil{return nil,err}; defer rows.Close()
	var out []Resource

	for rows.Next(){ var x Resource; var raw []byte; if err:=rows.Scan(&x.ID,&x.AccountID,&x.Provider,&x.ProviderResourceID,&x.Type,&x.State,&x.Managed,&raw,&x.CreatedAt,&x.UpdatedAt);err!=nil{return nil,err}; _=json.Unmarshal(raw,&x.Metadata); out=append(out,x) }
	return out,rows.Err()
}

func Compare(local, provider []Resource) []Difference {
	localByKey := make(map[string]Resource, len(local))
	remoteByKey := make(map[string]Resource, len(provider))
	for _, r := range local {
		localByKey[key(r)] = r
	}
	for _, r := range provider {

	remoteByKey[key(r)] = r
}
out := make([]Difference, 0)
for k, remote := range remoteByKey {
	localResource, ok := localByKey[k]
	if !ok {
		out = append(out, Difference{Kind: UnknownProviderResource, Resource: remote})
		continue

	}
	if localResource.State != remote.State {
		out = append(out, Difference{Kind: StateChanged, Resource: remote})
	}
}
for k, localResource := range localByKey {
	if _, ok := remoteByKey[k]; !ok {
		out = append(out, Difference{Kind: MissingProviderResource, Resource: localResource})

		}
	}
	return out
}

func key(r Resource) string {
	return r.Provider + ":" + r.AccountID + ":" + r.Type + ":" + r.ProviderResourceID
}

package resources

import "testing"

func TestCompareDetectsDifferences(t *testing.T) {
	local := []Resource{{AccountID: "a", Provider: "digitalocean", ProviderResourceID: "1", Type: "droplet", State: "active"}, {AccountID: "a", Provider: "digitalocean", ProviderResourceID: "2", Type: "droplet", State: "active"}}
	remote := []Resource{{AccountID: "a", Provider: "digitalocean", ProviderResourceID: "1", Type: "droplet", State: "off"}, {AccountID: "a", Provider: "digitalocean", ProviderResourceID: "3", Type: "droplet", State: "active"}}
	diffs := Compare(local, remote)

	seen := map[string]bool{}
	for _, d := range diffs {
		seen[d.Kind] = true
	}
	if !seen[StateChanged] || !seen[UnknownProviderResource] || !seen[MissingProviderResource] {
		t.Fatalf("missing differences: %#v", diffs)
	}
}

